{
  "title": "The Clockwork Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a crumbling map of the ruined city.",
      "visual_description": "Mara the Cartographer stands in a ragged plaza, unrolling a torn parchment map while the sun sets behind collapsed towers.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The Oracle Lamp flickers inside a shattered fountain, its single flame-eye narrowing as it speaks to Mara.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Glass Diver swims through a mirror into the city.",
      "visual_description": "Glass Diver presses his helmet against a broken window and steps through as if swimming, his coat trailing shimmering reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox sniffs out a hidden passage beneath old banners.",
      "visual_description": "Tin Fox's blue glass eyes glow as it scratches at a loose stone under faded royal banners hanging from a wall.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Sleeping Tax Collector is found dozing in a guardhouse.",
      "visual_description": "Inside a dusty guardhouse, the Sleeping Tax Collector snores with a ledger under his head, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara rouses the collector for information.",
      "visual_description": "Mara shakes the collector's shoulder while Oracle Lamp hovers close, casting a sharp light on his face.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Glass Diver scries the castle gates through a puddle.",
      "visual_description": "Glass Diver kneels by a murky puddle, his helmet dipping close as he peers into the reflection of distant castle gates.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox disables a tripwire near a magic door.",
      "visual_description": "Tin Fox carefully bites through a thin wire connected to a glowing rune on a stone archway.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The group gathers before a sealed door of black glass.",
      "visual_description": "Mara, Glass Diver, Oracle Lamp, and Tin Fox face a tall door of black glass that reflects their worried faces.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Glass Diver enters the glass door to unlock it from inside.",
      "visual_description": "Glass Diver presses both hands to the black glass and sinks into it, his form rippling like water until he disappears.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "A patrol of armored figures rounds a corner.",
      "visual_description": "From a side street, four armored figures march in lockstep, their visors blank and shields painted with faded crests.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp blinds the patrol with a flash.",
      "visual_description": "Oracle Lamp flares with brilliant white light, causing the armored figures to halt and shield their visors.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Glass Diver emerges from a fountain inside the castle.",
      "visual_description": "Glass Diver bursts upward from the water of a dry fountain in a courtyard, gasping and shedding mirror shards.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox finds a hidden lever behind a tapestry.",
      "visual_description": "Tin Fox pushes aside a moth-eaten tapestry and reveals a brass lever, its gears grinding into motion.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The magic door swings open for the group.",
      "visual_description": "The black glass door slides open silently, revealing a passage beyond where Glass Diver stands, helmet fogged.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "They cross a crumbling bridge under a red sky.",
      "visual_description": "The five figures hurry across a narrow stone bridge with missing balusters, a deep ravine below and red clouds above.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to collapse behind them.",
      "visual_description": "Stones plunge into the ravine as the bridge breaks in sections, Tin Fox leaping at the last moment.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side and pause to look back.",
      "visual_description": "The group stands on solid ground, breathing hard, watching the ruined city and its temptations recede in twilight.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ],
  "gate_token": "7PtvtAWrzG3LM9Fm7gItAg"
}

